// src/database/drizzle/sqlite-core/effect/query.ts
import { applyEffectWrapper } from "drizzle-orm/effect-core/query-effect";
import { entityKind } from "drizzle-orm/entity";
import {
  makeDefaultRqbMapper
} from "drizzle-orm/relations";
import { sql } from "drizzle-orm/sql/sql";

class SQLiteEffectRelationalQueryBuilder2 {
  schema;
  table;
  tableConfig;
  dialect;
  session;
  rowMode;
  forbidJsonb;
  static [entityKind] = "SQLiteEffectRelationalQueryBuilderV2";
  constructor(schema, table, tableConfig, dialect, session, rowMode, forbidJsonb) {
    this.schema = schema;
    this.table = table;
    this.tableConfig = tableConfig;
    this.dialect = dialect;
    this.session = session;
    this.rowMode = rowMode;
    this.forbidJsonb = forbidJsonb;
  }
  findMany(config) {
    return new SQLiteEffectRelationalQuery2(this.schema, this.table, this.tableConfig, this.dialect, this.session, config ?? true, "many", this.rowMode, this.forbidJsonb);
  }
  findFirst(config) {
    return new SQLiteEffectRelationalQuery2(this.schema, this.table, this.tableConfig, this.dialect, this.session, config ?? true, "first", this.rowMode, this.forbidJsonb);
  }
}

class SQLiteEffectRelationalQuery2 {
  schema;
  tableConfig;
  dialect;
  session;
  config;
  rowMode;
  forbidJsonb;
  static [entityKind] = "SQLiteEffectRelationalQueryV2";
  mode;
  table;
  constructor(schema, table, tableConfig, dialect, session, config, mode, rowMode, forbidJsonb) {
    this.schema = schema;
    this.tableConfig = tableConfig;
    this.dialect = dialect;
    this.session = session;
    this.config = config;
    this.rowMode = rowMode;
    this.forbidJsonb = forbidJsonb;
    this.mode = mode;
    this.table = table;
  }
  getSQL() {
    return this._getQuery().sql;
  }
  _prepare(isOneTimeQuery = true) {
    const { query, builtQuery } = this._toSQL();
    const mapperConfig = {
      isFirst: this.mode === "first",
      parseJson: !this.rowMode,
      parseJsonIfString: false,
      rootJsonMappers: true,
      selection: query.selection
    };
    return this.session[isOneTimeQuery ? "prepareOneTimeRelationalQuery" : "prepareRelationalQuery"](builtQuery, undefined, this.mode === "first" ? "get" : "all", makeDefaultRqbMapper(mapperConfig), mapperConfig);
  }
  prepare() {
    return this._prepare(false);
  }
  _getQuery() {
    const jsonb = this.forbidJsonb ? sql`json` : sql`jsonb`;
    const query = this.dialect.buildRelationalQuery({
      schema: this.schema,
      table: this.table,
      tableConfig: this.tableConfig,
      queryConfig: this.config,
      mode: this.mode,
      isNested: this.rowMode,
      jsonb
    });
    if (this.rowMode) {
      const jsonColumns = sql.join(query.selection.map((s) => {
        return sql`${sql.raw(this.dialect.escapeString(s.key))}, ${s.selection ? sql`${jsonb}(${sql.identifier(s.key)})` : sql.identifier(s.key)}`;
      }), sql`, `);
      query.sql = sql`select json_object(${jsonColumns}) as ${sql.identifier("r")} from (${query.sql}) as ${sql.identifier("t")}`;
    }
    return query;
  }
  _toSQL() {
    const query = this._getQuery();
    const builtQuery = this.dialect.sqlToQuery(query.sql);
    return { query, builtQuery };
  }
  toSQL() {
    return this._toSQL().builtQuery;
  }
  execute(placeholderValues) {
    return this.mode === "first" ? this._prepare().get(placeholderValues) : this._prepare().all(placeholderValues);
  }
}
applyEffectWrapper(SQLiteEffectRelationalQuery2);

export { SQLiteEffectRelationalQueryBuilder2, SQLiteEffectRelationalQuery2 };
